"""Build the journal, special journeys and education vision from owned source data."""
from pathlib import Path
from urllib.parse import urlencode
from datetime import date
import json, math, re
import build_tours as site

ROOT=site.ROOT
ARTICLES=json.loads((ROOT/'data/articles.json').read_text(encoding='utf-8'))
SPECIAL=json.loads((ROOT/'data/special-journeys.json').read_text(encoding='utf-8'))['journeys']
CATEGORIES={
    'trekking':('Kilimanjaro','images/package-covers/kilimanjaro-lava-tower-trail.webp','Trekkers on Kilimanjaro’s upper slopes near Lava Tower','Routes, preparation and mountain time'),
    'safari':('Safari','images/package-covers/serengeti-elephant-herd.webp','An elephant herd in Serengeti National Park','Wildlife, seasons and routes that work'),
    'zanzibar':('Zanzibar','images/stories/zanzibar-blue-water.webp','Boats on turquoise Zanzibar water','Island bases, tides and reef days'),
    'local':('Local life','images/stories/coffee-cherries.webp','Coffee cherries on a leafy branch','Village days and host-led experiences'),
    'purpose':('Education & purpose','images/optimized/kilimanjaro-guide.webp','David and a traveller on a Kilimanjaro trail','The education vision and its next steps'),
    'planning':('Trip planning','images/stories/zebras-safari-vehicle.webp','Safari vehicle and zebras','Quotes, connections and useful details'),
}
esc=site.esc
PAGE_NAMES={'trekking':'journal-kilimanjaro','safari':'journal-safari','zanzibar':'journal-zanzibar','local':'journal-local-life','purpose':'journal-education','planning':'journal-planning'}

def human_date(value):
    day=date.fromisoformat(value)
    return f'{day.day} {day.strftime("%B")} {day.year}'

def reading_minutes(article):
    text=' '.join([article['lede']]+[value for section in article['sections'] for value in section.get('paragraphs',[])+section.get('list',[])])
    return max(1,math.ceil(len(text.split())/200))

def article_card(article):
    id=article['id'];label=CATEGORIES[article['category']][0]
    return f'''<article class="journal-card" data-article-id="{id}"><a class="journal-card-image" href="{id}.html" aria-label="Read {esc(article['title'])}">{site.img(article['image'],article['alt'])}</a><div class="journal-card-body"><p class="journal-meta">{esc(label)} · {reading_minutes(article)} min read</p><h3><a href="{id}.html">{esc(article['title'])}</a></h3><p>{esc(article['excerpt'])}</p><div class="journal-card-actions"><a class="text-link" href="{id}.html">Read the guide ↗</a><button type="button" data-save-article="{id}" aria-pressed="false" hidden>Save for later</button></div><p class="journal-save-status" data-article-status role="status"></p></div></article>'''

def related(ids):
    cards=[]
    for id in ids:
        tour=next(t for t in site.TOURS if t['id']==id)
        cards.append(f'<article class="journey-small-card"><a href="{id}.html">{site.img(tour["image"],site.image_alt(tour))}<div><p class="journal-meta">{esc(tour["duration"])}</p><h3>{esc(tour["title"])}</h3><span class="text-link">View itinerary ↗</span></div></a></article>')
    return '<div class="journey-small-grid">'+''.join(cards)+'</div>'

def signature_cards():
    cards=[]
    for item in SPECIAL:
        tour=next(t for t in site.TOURS if t['id']==item['id'])
        cards.append(f'<article class="signature-card"><a class="signature-image" href="{tour["id"]}.html" aria-label="View {esc(tour["title"])}">{site.img(tour["image"],site.image_alt(tour),sizes="(max-width: 650px) 90vw, (max-width: 1000px) 45vw, 25vw")}</a><div><p class="signature-theme">{esc(item["theme"])}</p><h3><a href="{tour["id"]}.html">{esc(tour.get("cardTitle",tour["title"]))}</a></h3><p class="signature-duration">{esc(tour.get("cardDuration",tour["duration"]))}</p><p class="signature-summary">{esc(tour.get("cardSummary",tour["summary"]))}</p><p class="signature-arrangements">Private dates · personal written quote</p><a class="text-link" href="{tour["id"]}.html">Explore this journey ↗</a></div></article>')
    return '<div class="signature-grid">'+''.join(cards)+'</div>'

def category_tiles(exclude=None):
    cards=[]
    for id,(label,image,alt,description) in CATEGORIES.items():
        if id==exclude:continue
        count=sum(a['category']==id for a in ARTICLES)
        cards.append(f'<a class="journal-topic-card" href="{PAGE_NAMES[id]}.html">{site.img(image,alt)}<div><span class="eyebrow">{count} {("GUIDES" if count!=1 else "GUIDE")}</span><h3>{esc(label)}</h3><p>{esc(description)}</p><span class="text-link">Explore the articles ↗</span></div></a>')
    return '<div class="journal-topic-grid">'+''.join(cards)+'</div>'

def hero(eyebrow,title,text,image,alt,caption,link,label):
    return f'<section class="section editorial-hero"><div><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{text}</p><a class="btn btn-primary" href="{link}">{label} ↗</a></div><figure>{site.img(image,alt,True,"(max-width: 800px) 90vw, 50vw")}<figcaption>{caption}</figcaption></figure></section>'

def enhance(path):
    text=path.read_text(encoding='utf-8')
    if 'src="journal.js"' not in text:text=text.replace('</body>','<script src="journal-data.js" defer></script><script src="journal.js" defer></script></body>')
    path.write_text(text,encoding='utf-8')

def category_page(key):
    label,image,alt,description=CATEGORIES[key]
    articles=sorted((a for a in ARTICLES if a['category']==key),key=lambda a:a['date'],reverse=True)
    body=hero('DAVID EXPLORA JOURNAL · '+esc(label.upper()),esc(label)+'<br>travel notes.',esc(description)+'. Original guides to help you prepare questions and choose a suitable itinerary.',image,alt,'Destination photograph · <a href="photo-credits.html">Photo credits</a>','#category-articles','Explore the guides')
    body+='<section class="section" id="category-articles"><div class="section-heading"><p class="eyebrow">RECENT &amp; USEFUL GUIDES</p><h2>'+esc(label)+' in practical detail.</h2><p>'+str(len(articles))+' original '+('guide' if len(articles)==1 else 'guides')+' · <a href="journal.html#journal-articles">Search all subjects</a></p></div><div class="journal-card-grid">'+''.join(article_card(a) for a in articles)+'</div></section>'
    body+='<section class="section journal-index"><div class="section-heading"><p class="eyebrow">ALL ARTICLES IN THIS SUBJECT</p><h2>Your reading index.</h2></div><ul class="journal-category-index">'+''.join(f'<li><a href="{a["id"]}.html">{esc(a["title"])}</a></li>' for a in articles)+'</ul></section>'
    body+='<section class="section journal-categories"><div class="section-heading"><p class="eyebrow">EXPLORE ANOTHER PART OF TANZANIA</p><h2>Other journal subjects.</h2></div>'+category_tiles(key)+'</section>'
    schema={'@context':'https://schema.org','@type':'CollectionPage','name':label+' travel guides','url':site.ORIGIN+'/'+PAGE_NAMES[key]+'.html','hasPart':[{'@type':'Article','headline':a['title'],'url':site.ORIGIN+'/'+a['id']+'.html'} for a in articles]}
    site.page(PAGE_NAMES[key]+'.html',label+' Travel Guides',description+'. Browse David Explora’s original guides and related Tanzania itineraries.',body,image,schema)
    enhance(ROOT/(PAGE_NAMES[key]+'.html'))

def journal():
    first=ARTICLES[0]
    body=hero('DAVID EXPLORA JOURNAL','Know the place.<br>Plan the journey.','Practical Tanzania guides, a local perspective and the details behind a thoughtful trip. Read by destination, save a guide and follow it through to a suitable itinerary.',first['image'],first['alt'],first['caption'],'#journal-articles','Explore the journal')
    body+='<section class="section journal-categories"><div class="section-heading"><p class="eyebrow">FIND YOUR SUBJECT</p><h2>Six ways into Tanzania.</h2><p>Find a guide for your next trip, with practical route advice, related itineraries and links to the official information you may need.</p></div>'+category_tiles()+'</section>'
    options=''.join(f'<option value="{id}">{esc(value[0])}</option>' for id,value in CATEGORIES.items())
    body+=f'''<section class="section" id="journal-articles" data-journal-library><div class="section-heading split-heading"><div><p class="eyebrow">LOCAL KNOWLEDGE, IN USEFUL DETAIL</p><h2>Guides for your Tanzania trip.</h2></div><p>Choose a subject or search for a place, question or experience. Saved guides stay on this browser.</p></div><form class="journal-filters" id="journal-filters" role="search" aria-label="Search travel guides" hidden><div><label for="journal-query">What would you like to understand?</label><input id="journal-query" name="q" type="search" placeholder="Marangu, seasons, tides…" maxlength="120"></div><div><label for="journal-category">Subject</label><select id="journal-category" name="category"><option value="all">All subjects</option>{options}</select></div><div class="journal-saved-filter"><label for="journal-saved"><input id="journal-saved" type="checkbox"> My saved guides</label></div><button type="button" id="journal-reset">Reset</button></form><p id="journal-count" class="journal-result-count" role="status">{len(ARTICLES)} guides to explore</p><div class="journal-card-grid">{''.join(article_card(a) for a in ARTICLES)}</div><div class="journal-empty" id="journal-empty" hidden><h3>No guides match those choices.</h3><p>Try a broader search or reset the filters. David can help with a question about your trip.</p><a href="index.html#contact">Ask David ↗</a></div></section>'''
    index=''.join(f'<div><h3>{esc(label[0])}</h3><ul>'+''.join(f'<li><a href="{a["id"]}.html">{esc(a["title"])}</a></li>' for a in ARTICLES if a['category']==id)+'</ul></div>' for id,label in CATEGORIES.items())
    body+='<section class="section journal-index"><div class="section-heading"><p class="eyebrow">EVERY GUIDE, IN ONE PLACE</p><h2>A complete article index.</h2></div><div class="journal-index-grid">'+index+'</div></section>'
    schema={'@context':'https://schema.org','@type':'CollectionPage','name':'David Explora Journal','url':site.ORIGIN+'/journal.html','hasPart':[{'@type':'Article','headline':a['title'],'url':site.ORIGIN+'/'+a['id']+'.html'} for a in ARTICLES]}
    site.page('journal.html','Tanzania Travel Journal & Planning Guides','Original Kilimanjaro, safari, Zanzibar and local travel guides, plus David Explora’s education vision. Browse subjects, search and save useful articles.',body,first['image'],schema)
    enhance(ROOT/'journal.html')

def article_page(article):
    toc=''.join(f'<li><a href="#{esc(s["id"])}">{esc(s["title"])}</a></li>' for s in article['sections'])
    sections=[]
    for section in article['sections']:
        paragraphs=''.join(f'<p>{esc(p)}</p>' for p in section.get('paragraphs',[]))
        points='<ul>'+''.join(f'<li>{esc(p)}</li>' for p in section['list'])+'</ul>' if section.get('list') else ''
        sections.append(f'<section id="{esc(section["id"])}"><h2>{esc(section["title"])}</h2>{paragraphs}{points}</section>')
    sources=''.join(f'<li><a href="{esc(s["url"])}">{esc(s["label"])} ↗</a></li>' for s in article['sources'])
    additional=[a for a in ARTICLES if a['id']!=article['id'] and a['category']==article['category']]
    additional=(additional+[a for a in ARTICLES if a['id']!=article['id'] and a not in additional])[:2]
    body=f'''<progress class="article-progress" data-reading-progress max="100" value="0" aria-label="Article reading progress" hidden></progress><article data-reading-article><header class="section article-heading"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><a href="journal.html">Journal</a><span aria-hidden="true">/</span><a href="{PAGE_NAMES[article['category']]}.html">{esc(CATEGORIES[article['category']][0])}</a></nav><p class="eyebrow">DAVID EXPLORA · {esc(CATEGORIES[article['category']][0].upper())}</p><h1>{esc(article['title'])}</h1><p class="article-lede">{esc(article['lede'])}</p><p class="article-byline">David Explora planning notes · <time datetime="{article['date']}">{human_date(article['date'])}</time> · {reading_minutes(article)} min read</p><div class="journal-reading-tools"><button type="button" data-save-article="{article['id']}" aria-pressed="false" hidden>Save for later</button><button type="button" data-print-itinerary hidden>Print / save guide PDF</button><a href="journal.html?saved=1#journal-articles">My reading list ↗</a></div><p class="journal-save-status" data-article-status role="status"></p></header><figure class="article-cover">{site.img(article['image'],article['alt'],True,'90vw')}<figcaption>{esc(article['caption'])} · <a href="photo-credits.html">Photo credits</a></figcaption></figure><div class="section article-layout"><aside class="article-toc"><nav aria-label="In this guide"><p class="eyebrow">IN THIS GUIDE</p><ol>{toc}</ol></nav><a class="text-link" href="index.html#contact">Plan with David ↗</a></aside><div class="article-prose">{''.join(sections)}<section class="article-sources" id="sources"><h2>Sources &amp; further reading</h2><p>Sources reviewed for this guide on {human_date(article['date'])}. Current routes, prices and operating conditions are confirmed for your dates. These sources do not indicate a partnership or endorsement.</p><ul>{sources}</ul></section></div></div></article><section class="section article-related"><div class="section-heading"><p class="eyebrow">FROM THE GUIDE TO YOUR JOURNEY</p><h2>Explore the related itineraries.</h2></div>{related(article['related'])}</section><section class="section"><div class="section-heading"><p class="eyebrow">KEEP READING</p><h2>A little more local knowledge.</h2></div><div class="journal-card-grid journal-two-cards">{''.join(article_card(a) for a in additional)}</div></section>'''
    schema={'@context':'https://schema.org','@type':'Article','headline':article['title'],'description':article['excerpt'],'datePublished':article['date'],'dateModified':article['date'],'author':{'@type':'Organization','name':'David Explora','url':site.ORIGIN+'/about-david.html'},'publisher':{'@type':'Organization','name':'David Explora','url':site.ORIGIN},'image':site.ORIGIN+'/'+article['image'],'mainEntityOfPage':site.ORIGIN+'/'+article['id']+'.html','articleSection':CATEGORIES[article['category']][0]}
    site.page(article['id']+'.html',article['title'],article['excerpt'],body,article['image'],schema)
    path=ROOT/(article['id']+'.html');text=path.read_text(encoding='utf-8').replace('property="og:type" content="website"','property="og:type" content="article"');path.write_text(text,encoding='utf-8');enhance(path)

def specials():
    cards=[]
    for item in SPECIAL:
        tour=next(t for t in site.TOURS if t['id']==item['id'])
        control=f'<div class="journey-compare-choice" hidden><label for="compare-{tour["id"]}"><input type="checkbox" id="compare-{tour["id"]}" data-compare-tour="{tour["id"]}"> Compare this journey</label></div>'
        cards.append('<div class="special-journey-item"><p class="eyebrow">'+esc(item['theme'])+'</p>'+site.card(tour)+control+'</div>')
    body=hero('SIGNATURE IDEAS · PRIVATE DATES','A journey with<br>room for your story.','Connect the mountain, wildlife, local life or the coast with a route that allows time for the journey itself. Four special itineraries start the conversation; your dates and group shape the final plan.','images/stories/marangu-moorland.webp','A trekker resting in Kilimanjaro moorland','Kilimanjaro · photograph supplied by David Explora','#special-itineraries','Explore the special journeys')
    body+='<div class="daytrip-navigation"><p>Private dates on request · personal written quotes</p><div><a href="#special-itineraries">Four journeys</a><a href="#journey-comparison">Compare the details</a><a href="#travel-purpose">Education vision</a><a href="journal.html">Planning articles</a></div></div>'
    body+='<section class="section" id="special-itineraries"><div class="section-heading split-heading"><div><p class="eyebrow">MOUNTAIN · WILDLIFE · PEOPLE · COAST</p><h2>Choose the combination<br>that means something to you.</h2></div><p>Every itinerary has a realistic arrival and departure plan. Nights, transfers and optional activities are stated; prices are quoted for your actual party.</p></div><div class="special-journey-grid">'+''.join(cards)+'</div></section>'
    rows=[('Duration',lambda t:t['duration']),('Overnights',lambda t:str(t['nights'])+' nights'),('Mountain time',lambda t:str(t.get('mountainDays',0))+' mountain days' if t.get('mountainDays') else 'No summit trek'),('Best fit',lambda t:next(j['for'] for j in SPECIAL if j['id']==t['id'])),('Starts / ends',lambda t:t['start']),('Main experiences',lambda t:' · '.join(t['places'])),('Price',lambda t:'Personal quote for your dates and group'),('Education support',lambda t:'No donation or school visit included')]
    all_tours=[next(t for t in site.TOURS if t['id']==s['id']) for s in SPECIAL]
    heads=''.join(f'<th scope="col"><a href="{t["id"]}.html">{esc(t["title"])}</a></th>' for t in all_tours)
    lines=''.join(f'<tr><th scope="row">{esc(label)}</th>'+''.join(f'<td>{esc(fn(t))}</td>' for t in all_tours)+'</tr>' for label,fn in rows)
    body+=f'<section class="section journey-comparison" id="journey-comparison" data-journey-comparison><div class="section-heading"><p class="eyebrow">COMPARE BEFORE YOU CHOOSE</p><h2>The practical differences.</h2><p>Compare the complete trip, including its overnight plan. With JavaScript enabled, choose up to three journeys above for a shorter comparison.</p></div><p data-compare-status role="status">Showing all four special journeys.</p><div class="route-comparison-table" tabindex="0" role="region" aria-label="Special journey comparison, scroll horizontally on small screens"><table><caption>Special journey duration, nights and travel scope</caption><thead><tr><th scope="col">Detail</th>{heads}</tr></thead><tbody>{lines}</tbody></table></div></section>'
    body+='<section class="section purpose-travel-note" id="travel-purpose"><p class="eyebrow">GOOD TRAVEL. A LONGER-TERM PURPOSE.</p><h2>The journey is real.<br>The education vision is growing.</h2><p>These are travel itineraries, with paid local guiding and agreed services. David’s separate education vision aims to help young people continue learning. It is in development; no donation or access to a school is included in a travel booking.</p><a class="btn btn-primary" href="education-vision.html">Explore the education vision ↗</a><a class="text-link" href="education-through-tourism.html">Read why this matters to David ↗</a></section>'
    schema={'@context':'https://schema.org','@type':'ItemList','name':'David Explora special journeys','itemListElement':[{'@type':'ListItem','position':n+1,'name':t['title'],'url':site.ORIGIN+'/'+t['id']+'.html'} for n,t in enumerate(all_tours)]}
    site.page('special-journeys.html','Special Tanzania Journeys','Compare four private Tanzania journeys: Kilimanjaro and safari, safari and local life, men’s Kilimanjaro travel, and Zanzibar culture and coast.',body,'images/stories/marangu-moorland.webp',schema);enhance(ROOT/'special-journeys.html')

def education():
    message='Hello David, I would like to discuss the Explora Education Vision and its proposed first pilot. My connection to education or community work is: '
    whatsapp='https://wa.me/255778321400?'+urlencode({'text':message})
    email='mailto:davidlyamuya819@gmail.com?'+urlencode({'subject':'Explora Education Vision — partnership enquiry','body':message})
    body=hero('THE EXPLORA EDUCATION VISION','Let travel open<br>a path to learning.','My long-term aim is to build a tourism business that can help young people continue their education. Start with a real local need, a responsible partner and a small commitment that can be followed through.','images/optimized/kilimanjaro-guide.webp','David with a traveller on a Kilimanjaro trail','David on a Kilimanjaro trail · photograph supplied by David Explora','#education-roadmap','See the development plan')
    body+='''<section class="section education-status"><p class="eyebrow">CURRENT STAGE · 14 OCTOBER 2026</p><h2>An idea being built with care.</h2><p>This is David’s proposal for a small education pilot. The partner, budget and delivery arrangements are still to be agreed. No education donations are being collected, and travel bookings do not carry an automatic contribution.</p><p>Educators, responsible local organisations and travellers with relevant experience can help shape a practical first pilot.</p></section><section class="section"><div class="section-heading split-heading"><div><p class="eyebrow">THE AIM</p><h2>Keep learning.<br>Build useful skills.<br>Widen the possibilities.</h2></div><p>Continuing my own education through difficult circumstances has shaped how I see opportunity. I want David Explora’s future to help young people who are working towards their education and need practical support, guided by educators who understand their circumstances.</p></div><div class="education-focus-grid"><article><span>01</span><h3>Stay in education</h3><p>Explore a small pilot for verified learning materials or education costs, agreed through an appropriate local partner. Selection and payments would be documented before any support begins.</p></article><article><span>02</span><h3>Skills for the next step</h3><p>Consider supervised language, digital and tourism-skills mentoring. The programme would use realistic learning goals and qualified people, rather than promise jobs or qualifications.</p></article><article><span>03</span><h3>Local voices lead</h3><p>Ask educators and community organisations which needs matter first. Students’ private circumstances and identities should not become marketing material.</p></article></div></section>'''
    stages=[('01','Now','Define the vision','Publish the proposed purpose, make the current stage clear and invite responsible partnership conversations.'),('02','Next','Listen and verify','Speak with educators and suitable organisations; agree needs, selection criteria, safeguarding and the responsible delivery arrangements.'),('03','Before any fundraising','Cost one pilot','Name the partner, agreed support, target cost, payment route, record-keeping and reporting method. Confirm the required operating arrangements before launch.'),('04','After launch','Deliver and report','Record contributions separately from travel revenue, document the agreed support and publish factual progress without exposing students’ private details.')]
    timeline=''.join(f'<li><span>{n}</span><div><p class="eyebrow">{phase}</p><h3>{title}</h3><p>{text}</p></div></li>' for n,phase,title,text in stages)
    body+=f'<section class="section education-roadmap" id="education-roadmap"><div class="section-heading"><p class="eyebrow">SMALL ENOUGH TO DELIVER. CLEAR ENOUGH TO CHECK.</p><h2>From a vision to a first pilot.</h2><p>The first stage is current. Later stages are proposed work, not completed milestones.</p></div><ol>{timeline}</ol></section>'
    body+='''<section class="section education-principles"><div class="section-heading"><p class="eyebrow">WHAT A FUTURE PROGRAMME SHOULD MAKE CLEAR</p><h2>Respect, before publicity.</h2></div><div class="education-focus-grid"><article><h3>People and consent</h3><p>Work through appropriate responsible organisations, protect personal information and agree supervision before any mentoring. No classroom drop-ins or access to children are sold as tour attractions.</p></article><article><h3>Money and records</h3><p>Keep travel payments and support contributions distinct. Any future contribution per booking would be stated in writing before that offer begins; no percentage is promised today.</p></article><article><h3>Evidence and updates</h3><p>A future report would distinguish funds received, agreed costs, support delivered and remaining work. Progress would be published only after it can be checked against the delivery records.</p></article></div><p class="photo-note">Safeguarding context: <a href="https://www.unicef.org/who-we-are/safeguarding">UNICEF safeguarding</a> and <a href="https://www.unicef.org/tanzania/reports/assessment-impact-tourism-communities-and-children-zanzibar">UNICEF Tanzania’s tourism assessment</a>. David Explora does not claim a UNICEF affiliation.</p></section>'''
    body+=f'''<section class="section education-contact" id="education-contact"><p class="eyebrow">HELP SHAPE SOMETHING USEFUL</p><h2>Bring your experience<br>to the first conversation.</h2><p>If you work in education, community development or responsible tourism, tell David what you can help assess. Travellers can express interest in future updates. Your message is an enquiry, not a donation or a subscription.</p><div class="hero-buttons"><a class="btn btn-primary" href="{esc(whatsapp)}" target="_blank" rel="noopener noreferrer">Discuss the vision on WhatsApp ↗</a><a class="btn btn-secondary" href="{esc(email)}">Email a partnership idea ↗</a></div><p class="photo-note">Your app opens a draft. Review it and press Send there to deliver it. Please do not send students’ names, photos, medical details or private school records in an initial enquiry. <a href="privacy.html">Privacy information</a>.</p><a class="text-link" href="education-through-tourism.html">Read David’s education article ↗</a></section>'''
    site.page('education-vision.html','Explora Education Vision','David Explora’s proposed education-support initiative: a local, accountable pilot for learning and skills. See its current stage, development plan and partnership contact.',body,'images/optimized/kilimanjaro-guide.webp')

def about():
    body=hero('DAVID AMANI LYAMUYA · LOCAL GUIDE','The places I know.<br>The future I want to build.','I’m David, a guide from Marangu in the Kilimanjaro foothills. David Explora brings together mountain routes, wildlife journeys, island days and the practical details between them.','images/stories/marangu-huts.webp','David beside mountain huts on the Marangu route','A mountain moment · photograph supplied by David Explora','index.html#contact','Plan with David')
    body+='''<section class="section founder-story"><div class="founder-portrait-line"><img src="images/stories/david-portrait.webp" alt="David Amani Lyamuya" width="120" height="150" loading="lazy" decoding="async"><p>David Amani Lyamuya<br>Guiding, planning and continuing to learn</p></div><p class="eyebrow">WHERE THE IDEA STARTS</p><h2>Local knowledge,<br>with a clear plan.</h2><p>David Explora starts with a conversation. You tell me what you want from your time in Tanzania, and I help turn that into a route with the right number of days, clear arrangements and a price you can understand.</p><p>I grew up in the Marangu region, where the mountain and everyday village life meet. Guiding has taught me to listen to a traveller’s pace and explain what the day involves. My tourism management and marketing studies help me build that practical experience into a better-planned business. David Explora is a young venture I am developing with care, one well-organised journey at a time.</p><p>I speak English and Kiswahili and am developing my Spanish. If you need a Spanish-speaking guide or individual support, tell me early so the actual arrangements can be checked for your dates. Each written itinerary explains who guides the activities and how the transfers, accommodation and costs fit together.</p></section>'''
    scopes=[('mountain','Kilimanjaro','Forest day hikes and six-, seven- or eight-day mountain routes, with arrival time, crew arrangements and preparation discussed before confirmation.','images/stories/marangu-moorland.webp','A trekker in Kilimanjaro moorland','kilimanjaro.html'),('safari','Wildlife journeys','Northern plains or southern river country, with the actual departure point, safari nights and park travel visible in the route.','images/safari-expansion/serengeti-plains.webp','Serengeti landscape','safari.html'),('local','Village and city life','Moshi and Arusha walks, Marangu coffee and other host-led days, with public meeting points, permission and paid local services.','images/stories/coffee-cherries.webp','Coffee cherries','local-tanzania.html'),('coast','Zanzibar','Heritage streets, spices, forest and the ocean. Choose the coast and activities around your hotel and the day’s conditions.','images/stories/zanzibar-blue-water.webp','Boats on turquoise Zanzibar water','zanzibar.html')]
    cards=''.join(f'<article>{site.img(image,alt)}<div>{site.features.icon(icon)}<h3>{title}</h3><p>{text}</p><a class="text-link" href="{link}">Explore {title} ↗</a></div></article>' for icon,title,text,image,alt,link in scopes)
    body+='<section class="section founder-scopes"><div class="section-heading"><p class="eyebrow">FOUR PARTS OF THE SAME TANZANIA STORY</p><h2>What I help you plan.</h2></div><div>'+cards+'</div></section>'
    body+='''<section class="section founder-vision"><p class="eyebrow">THE PURPOSE BEYOND THE NEXT JOURNEY</p><h2>Education is part<br>of the long-term dream.</h2><p>The difficulties I have faced in continuing my own education are part of this ambition. I want to build a tourism business that can help young people keep learning, develop useful skills and take their next step with confidence. The Explora Education Vision gives that ambition a practical starting plan.</p><p>The initiative is in development. The current task is to listen, find appropriate partners and define one accountable pilot.</p><a class="btn btn-primary" href="education-vision.html">Explore the education vision ↗</a><a class="text-link" href="journal.html">Read the David Explora journal ↗</a></section>'''
    site.page('about-david.html','Meet David & the David Explora Vision','Meet David Amani Lyamuya, a local guide from Marangu, and explore David Explora’s Tanzania journeys, planning approach and proposed education vision.',body,'images/stories/marangu-huts.webp')

def homepage():
    path=ROOT/'index.html';text=path.read_text(encoding='utf-8')
    small=signature_cards()
    signature=f'<section class="section home-special-journeys" id="special-journeys"><div class="section-heading split-heading"><div><p class="eyebrow">MOUNTAIN · WILDLIFE · LOCAL LIFE · COAST</p><h2>Journeys that<br>fit together.</h2></div><p>Four private itinerary ideas with time for the places between the highlights. Compare the full travel days, then ask David to check the route and arrangements for your group. <a href="special-journeys.html">Compare special journeys ↗</a></p></div>{small}</section>'
    education_block=f'<section class="section home-education"><figure>{site.img("images/stories/marangu-huts.webp","David beside mountain huts on the Marangu route")}<figcaption>A guiding moment · photograph supplied by David Explora</figcaption></figure><div><p class="eyebrow">A LOCAL JOURNEY. A LONGER-TERM VISION.</p><h2>My next ambition:<br>help more young people learn.</h2><p>My own education journey has shaped this ambition. I want the business I am building to help young people facing difficult circumstances continue learning, with support based on real local needs and responsible partnerships.</p><p class="education-stage">Explora Education Vision · in development</p><a class="btn btn-primary" href="education-vision.html">See the vision and first steps ↗</a><p class="photo-note">A proposed initiative. The first partners, budget and delivery plan are still being developed.</p></div></section>'
    chosen=[next(a for a in ARTICLES if a['id']==id) for id in ['christmas-on-kilimanjaro','christmas-safari-tanzania','zanzibar-coast-tides']]
    journal_block='<section class="section home-journal"><div class="section-heading split-heading"><div><p class="eyebrow">THE DAVID EXPLORA JOURNAL</p><h2>Read before you travel.</h2></div><p>Christmas mountain dates, shared safari plans and Zanzibar’s tides. Read practical guides by subject and bring your questions into the planning conversation. <a href="journal.html">Read all the guides ↗</a></p></div><div class="journal-card-grid">'+''.join(article_card(a) for a in chosen)+'</div></section>'
    for name,html in [('home-special',signature),('home-editorial',education_block+journal_block)]:
        text=re.sub(f'<!-- BEGIN: {name} -->.*?<!-- END: {name} -->',lambda _,h=html,n=name:f'<!-- BEGIN: {n} -->{h}<!-- END: {n} -->',text,flags=re.S)
    path.write_text(text,encoding='utf-8');enhance(path)

def build():
    metadata=[{**{key:a[key] for key in ['id','title','category','excerpt']},'searchText':' '.join([a['lede']]+[s['title']+' '+' '.join(s.get('paragraphs',[])+s.get('list',[])) for s in a['sections']])} for a in ARTICLES]
    (ROOT/'journal-data.js').write_text('/* Generated from data/articles.json and data/special-journeys.json. */\n(function(r,d){if(typeof module==="object"&&module.exports)module.exports=d;else r.DavidJournalData=d;})(globalThis,'+json.dumps({'articles':metadata,'journeys':SPECIAL},ensure_ascii=False)+');\n',encoding='utf-8')
    journal()
    for a in ARTICLES:article_page(a)
    for key in CATEGORIES:category_page(key)
    specials();education();about();homepage();site.sitemap()
    print(f'Built {len(ARTICLES)} original guides, journal, special journeys, education vision and founder page')

if __name__=='__main__':build()
